#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 510;

int M, N, MOD;

inline int addMod(int a, int b) { return (a + b) % MOD; }
inline int subMod(int a, int b) { return a - b < 0 ? a - b + MOD : a - b; }
inline int mulMod(int a, int b) { return (long long) a * b % MOD; }

int factorials[MAX_SIZE], invFactorials[MAX_SIZE], inverses[MAX_SIZE];

void initialize(int limit)
{
    factorials[0] = 1; inv[1] = 1; factorials[1] = 1; invFactorials[0] = 1; invFactorials[1] = 1;
    for (int i = 2; i <= limit; i++) inverses[i] = mulMod((MOD - MOD / i), inverses[MOD % i]);
    for (int i = 2; i <= limit; i++) { factorials[i] = mulMod(factorials[i - 1], i); invFactorials[i] = mulMod(invFactorials[i - 1], inverses[i]); }
}

int choose(int n, int r) {
    if (n < r || r < 0) return 0;
    return mulMod(mulMod(factorials[n], invFactorials[r]), invFactorials[n - r]);
}

int perm(int n, int r) {
    return choose(n + r - 1, r - 1);
}

int f_vals[MAX_SIZE], g_vals[MAX_SIZE], prefixSum[MAX_SIZE];
int f_table[MAX_SIZE][MAX_SIZE], g_table[MAX_SIZE][MAX_SIZE];

int main()
{
    scanf("%d %d %d", &N, &M, &MOD);
    initialize(500);
    for (int i = 1; i <= N; i++) prefixSum[i] = addMod(prefixSum[i - 1], i);
    f_vals[0] = 1; f_vals[1] = 2;
    g_vals[0] = 0; g_vals[1] = 0;
    for (int i = 2; i <= N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            int temp = mulMod(choose(i - 1, j), mulMod(f_vals[j], f_vals[i - 1 - j]));
            f_vals[i] = addMod(f_vals[i], mulMod(temp, i + 1));
            g_vals[i] = addMod(g_vals[i], mulMod(temp, prefixSum[j] + prefixSum[i - 1 - j]));
            int temp2 = mulMod(addMod(mulMod(g_vals[j], f_vals[i - 1 - j]), mulMod(g_vals[i - 1 - j], f_vals[j])), i + 1);
            g_vals[i] = addMod(g_vals[i], mulMod(temp2, choose(i - 1, j)));
        }
    }
    f_table[0][0] = 1; g_table[0][0] = 0;
    for (int i = 0; i <= M; i++)
        for (int j = 0; j <= M; j++)
        {
            if (f_table[i][j] == 0) continue;
            for (int k = 1; k + j <= M; k++)
            {
                f_table[i + 1][j + k] = addMod(f_table[i + 1][j + k], mulMod(mulMod(f_table[i][j], f_vals[k]), choose(j + k, k)));
                g_table[i + 1][j + k] = addMod(g_table[i + 1][j + k], mulMod(addMod(mulMod(g_table[i][j], f_vals[k]), mulMod(f_table[i][j], g_vals[k])), choose(j + k, k)));
            }
        }
    int result = 0;
    for (int i = 1; i <= M; i++)
        if (N + 1 - M >= i)
            result = addMod(result, mulMod(g_table[i][M], perm(N + 1 - M - i, i + 1)));
    printf("%d\n", result);
    return 0;
}
